/**
 * The model catalog's figures for the built-in rows, as the runtime holds them after its first catalog read; a
 * test installs them through the shipped config and `resetCatalogFigures` removes them. The figures are the
 * checked-in fixture, generated by `scripts/gen_builtin_catalog_figures.ts`.
 */
import fixture from '../catalog/fixtures/builtin-catalog-figures.json'
import {
  builtinFiguresDocument,
  type BuiltinCatalogFigures,
} from '../../catalog/builtinFiguresDocument'
import { SNAPSHOT_PROVIDER_KEYS } from '../../catalog/snapshotProviders'
import { setCatalogFigures } from '../../config/nexusModelConfig/catalogFigures'

export { builtinCatalogKey } from '../../catalog/builtinFiguresDocument'

export const BUILTIN_CATALOG_FIGURES = fixture as BuiltinCatalogFigures

export function installBuiltinCatalogFigures(): void {
  for (const [providerId, models] of Object.entries(BUILTIN_CATALOG_FIGURES)) {
    setCatalogFigures(providerId, [new Map(Object.entries(models))])
  }
}

/** One stand-in model, so a provider in a source document is not empty. */
const PLACEHOLDER_MODELS = {
  'some-model': { id: 'some-model', name: 'some-model', tool_call: true, modalities: { input: ['text'], output: ['text'] }, limit: { context: 8_192, output: 1_024 } },
}

/**
 * A document in the catalog source's own shape holding every snapshot
 * provider, with the fixture's figures under each built-in provider's
 * catalog key: a document the publish's coverage gate passes. `without`
 * names a catalog key whose models are swapped for the stand-in, so the
 * gate fails on that provider's rows.
 */
export function builtinCatalogSourceDocument(without?: string): Record<string, unknown> {
  return {
    ...Object.fromEntries(
      SNAPSHOT_PROVIDER_KEYS.map(key => [key, { id: key, name: key, models: PLACEHOLDER_MODELS }]),
    ),
    ...builtinFiguresDocument(BUILTIN_CATALOG_FIGURES, without),
  }
}
